collector_ps1.content:
# tick_collect_once.ps1 - zero-LLM collector wrapper (replaces LLM cron mt5-live-tick-collect, 2026-09-08)
# Runs the real collector script, writes truthful heartbeat, self-heals dashboard. ASCII only.
$ErrorActionPreference = 'Continue'
$out = & 'C:\AIQuant\.venv\Scripts\python.exe' 'C:\AIQuant\research\self_collect\mt5_live_collect.py' --once 2>&1 | Out-String
$now = (Get-Date).ToUniversalTime()

$result = 'UNKNOWN'
if ($out -match 'MT5_INIT_FAIL') { $result = 'MT5_INIT_FAIL' }
elseif ($out -match 'NO_NEW_TICKS_ALERT') { $result = 'NO_NEW_TICKS_ALERT' }
elseif ($out -match 'NO_NEW_TICKS') { $result = 'NO_NEW_TICKS' }
elseif ($out -match 'COLLECTED') { $result = 'COLLECTED' }

# truth from collector stdout (never hardcoded)
$summaryLine = ($out -split "`n" | Where-Object { $_ -match 'COLLECTED|TICK_ONLY|NO_NEW_TICKS|MT5_INIT_FAIL' } | Select-Object -Last 1)
$summary = ($summaryLine | Out-String).Trim()
$newN = 0; $totalN = 0
if ($summary -match 'new=(\d+)') { $newN = [int]$Matches[1] }
if ($summary -match 'total_day=(\d+)') { $totalN = [int]$Matches[1] }

# latest parquet truth
$pq = Get-ChildItem 'C:\AIQuant\data\live_fxtm' -Filter 'ticks_*.parquet' | Sort-Object LastWriteTime -Descending | Select-Object -First 1
if ($pq) { $tickFile = $pq.Name; $tickMtime = $pq.LastWriteTime.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') } else { $tickFile = 'none'; $tickMtime = '' }

# market_open heuristic: weekend/week (collector prints NO_NEW_TICKS w/o ALERT when weekend)
$wd = [int]$now.DayOfWeek  # 0=Sunday
$weekend = ($wd -eq 0) -or ($wd -eq 6) -or ($wd -eq 5 -and $now.Hour -ge 21) -or ($wd -eq 1 -and $now.Hour -lt 21)
if ($result -eq 'MT5_INIT_FAIL' -or $result -eq 'UNKNOWN') { $marketOpen = $false }
elseif ($result -eq 'NO_NEW_TICKS' -and $weekend) { $marketOpen = $false }
else { $marketOpen = $true }

$hb = @{
    timestamp       = $now.ToString('yyyy-MM-ddTHH:mm:ss.fffZ')
    result          = $result
    summary         = $summary
    tick_file       = $tickFile
    tick_rows       = $totalN
    new_ticks       = $newN
    tick_file_mtime = $tickMtime
    market_open     = $marketOpen
    note            = 'zero-LLM collector wrapper (schtasks every 15min)'
    detail          = (($out -split "`n" | Where-Object { $_ -match 'LIVE |SNAP|COLLECTED|NO_NEW_TICKS|MT5_INIT_FAIL' } | Select-Object -Last 2) -join ' | ').Trim()
} | ConvertTo-Json

Set-Content -Path 'C:\AIQuant\research\money_hunter\dashboard\heartbeat_tick.json' -Value $hb -Encoding UTF8

# dashboard self-heal (port 8787)
$listener = Get-NetTCPConnection -LocalPort 8787 -State Listen -ErrorAction SilentlyContinue
if (-not $listener) {
    Start-Process -FilePath 'C:\AIQuant\.venv\Scripts\python.exe' -ArgumentList 'research\money_hunter\dashboard\dashboard.py' -WorkingDirectory 'C:\AIQuant' -WindowStyle Hidden
}

# audit log
Add-Content -Path 'C:\AIQuant\data\live_fxtm\collect_runs.log' -Value ("{0}Z {1} {2}" -f $now.ToString('yyyy-MM-ddTHH:mm:ss'), $result, $summary) -Encoding UTF8

Write-Output ($result + ' ' + $summary)
